-- Intermediate 
SELECT * FROM products;
SELECT * FROM sales_transactions;

-- 1.Calculate the total revenue (net_amount) generated by each product category.
SELECT p.category, sum(s.net_amount) as Total_revenue, 
                   round(sum(s.net_amount)/(SELECT sum(net_amount) FROM sales_transactions)*100,2) as Percentage_amount
FROM products as p
INNER JOIN sales_transactions AS s
ON s.product_id = p.product_id
GROUP BY category
ORDER BY SUM(s.net_amount) desc;

-- 2 Find the top 5 customers by total amount spent, along with their city.
SELECT customer_id, customer_name, customer_city, SUM(net_amount) AS total_spend
FROM sales_transactions
GROUP BY customer_id, customer_name, customer_city
ORDER BY sum(net_amount) DESC
LIMIT 5;
-- extra q- Q2: Check whether the top 5 customers account for a large share of revenue. If they do, the business depends on a few customers.
SELECT SUM(total_spend)/(SELECT SUM(net_amount) FROM sales_transactions)*100 AS top_5revenue_cust_pct
FROM(SELECT customer_id, SUM(net_amount) AS total_spend
FROM sales_transactions
GROUP BY customer_id
ORDER BY sum(net_amount) DESC
LIMIT 5) AS TOP5;

SELECT MIN(discount_pct), MAX(discount_pct), MIN(discount_amount), MAX(discount_amount)
FROM sales_transactions;

-- count of repeted buyer customer
SELECT COUNT(DISTINCT customer_id)AS total_customer FROM sales_transactions;
SELECT (sum(net_amount)/(select count(DISTINCT customer_id) from sales_transactions)*100) AS avg_price_per_cust from sales_transactions;


-- 3 Calculate the average discount percentage given per store city.
SELECT store_city, AVG(discount_pct),sum(net_amount) FROM sales_transactions
GROUP BY store_city;

-- Compare the cities. A city with a high average discount but low net_amount suggests discounts are not bringing in revenue.
SELECT store_city, AVG(discount_pct), sum(net_amount) FROM sales_transactions
GROUP BY store_city;

-- 4 Find the number of transactions and total quantity sold for each payment mode.
SELECT payment_mode, count(transaction_id) as total_transactions, sum(quantity) as total_quantity
FROM sales_transactions
GROUP BY payment_mode;

-- 5 List all products that have never appeared in any sales transaction (products with zero sales).
SELECT * FROM products;
SELECT p.product_id, p.product_name FROM products AS p
LEFT JOIN sales_transactions AS s
ON p.product_id = s.product_id
WHERE s.transaction_id IS NULL;

-- 6.Calculate month-wise total sales revenue for the year 2025.
SELECT MONTHNAME(sale_date) AS Months, SUM(net_amount) AS TOTAL_AMOUNT, sum(net_amount)/(select sum(net_amount) FROM sales_transactions
where year(sale_date) = 2025)*100 as pct FROM sales_transactions
WHERE YEAR(sale_date) = 2025
GROUP BY MONTHNAME(sale_date);

-- 7. Find categories whose total revenue exceeds ₹5,00,000 using GROUP BY with HAVING.
SELECT p.category, sum(s.net_amount) as total FROM products as p 
INNER JOIN sales_transactions AS s
ON p.product_id = s.product_id
GROUP BY p.category
HAVING sum(s.net_amount)>500000;

-- 8. For each store city, find the single highest-value transaction (by net_amount).
SELECT store_city, MAX(net_amount) FROM sales_transactions
GROUP BY store_city;

SELECT product_name,store_city, transaction_id, sale_date, customer_name, p.product_id, net_amount
FROM (
	   SELECT *, RANK() OVER(PARTITION BY store_city ORDER BY net_amount DESC) AS rnk
       FROM sales_transactions
) AS RANKS
INNER JOIN products AS P 
ON P.product_id = RANKS.product_id
WHERE rnk = 1
ORDER BY net_amount DESC;

SELECT MIN(quantity), MAX(quantity), ROUND(AVG(quantity), 1) FROM sales_transactions;

SELECT p.product_name, p.selling_price,
       s.quantity, s.unit_price, s.discount_pct, s.discount_amount, s.net_amount,
       ROUND(s.quantity * s.unit_price - s.discount_amount, 2) AS calculated_net
FROM sales_transactions AS s
INNER JOIN products AS p
  ON p.product_id = s.product_id
WHERE s.transaction_id IN ('T502895','T500970','T505332','T504693','T500311',
                           'T503265','T501617','T502399','T501391','T503490')
ORDER BY s.net_amount DESC;

-- 9 Find the number of unique customers who made a purchase from each store city.
SELECT store_city, count(DISTINCT customer_id) AS uni_customers FROM sales_transactions
GROUP BY store_city;


-- 10
SELECT discount_pct, COUNT(*) AS rows_count
FROM sales_transactions
GROUP BY discount_pct
ORDER BY discount_pct;













